import {dialogueText} from './scenario-dialogue-text.js';
import {button,icon,esc,phraseText,quotedText} from './ui.js';
import {lessonNumberWithVideo} from './video-lesson-state.js';
import {scenarioProgress,scenarioTitle,scenarioLearnsFirst} from './scenario-state.js';
export function renderListeningIntent(s,top,l,c){
 const p=scenarioProgress(s),x=c.items[p.index],jp=s.courseDirection==='ja-ko',ui=jp?'ja':'ko',lang=jp?'ko':'ja',label=(ko,ja)=>jp?ja:ko;
 const sceneImage=c.image?`<img class="scenario-image" src="${esc(c.image)}" alt="" width="960" height="480" decoding="async">`:'';
 const ratio=p.phase==='intro'?0:Math.round((p.index*(scenarioLearnsFirst(l.id)?2:1)+(scenarioLearnsFirst(l.id)?1:0)+(p.checked?1:0))/(l.count*(scenarioLearnsFirst(l.id)?2:1))*100),header=top(`${lessonNumberWithVideo(s,l.number[s.courseDirection])}. ${scenarioTitle(s,l)}`);
 const progress=`<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${ratio}"><span style="width:${ratio}%"></span></div>`;
 if(p.phase==='intro')return `${header}${progress}<main class="page scenario-page lesson-top ${c.image?'scenario-illustrated':''}" lang="${ui}">${sceneImage}<h1>${esc(scenarioTitle(s,l))}</h1><p>${quotedText(c.scene)}</p>${button(scenarioLearnsFirst(l.id)?label('학습 시작하기','学習を始める'):label('듣고 고르기','聞いて選ぶ'),'scenario-next')}</main>`;
 const audio=(part='prompt')=>button(icon('sound'),'scenario-audio','icon-button',`data-id="${part}" aria-label="${label('다시 듣기','もう一度聞く')}"`);
 const learningText=(text,parts)=>c.weather&&lang==='ko'?esc(text):phraseText(text,parts||undefined);
 const translation=text=>`<details class="message-meaning"><summary>${label('뜻 보기','意味を見る')}</summary><p lang="${ui}">${quotedText(text)}</p></details>`;
 const transcript=`<div class="audio-text-row"><p lang="${lang}">${learningText(x.text,x.phrases)}</p>${audio()}</div>${!c.weather||p.checked?translation(x.meaning):''}`;
 const answerIndex=l.answers?.[p.index]??p.index,choices=[...x.others];choices.splice(answerIndex,0,x.answer);
 const meanings=[...(x.otherMeanings||[])];meanings.splice(answerIndex,0,x.answerMeaning);
 const resultAnswer=c.weather?`<div class="audio-text-row"><p class="intent-answer" lang="${lang}">${learningText(x.answer,x.answerParts)}</p>${audio('answer')}</div>${translation(x.answerMeaning)}`:`<p class="intent-answer">${quotedText(x.answer)}</p>`;
 return `${header}${progress}<main class="page scenario-page intent-page ${c.weather?'weather-page':''} ${c.image?'scenario-illustrated':''}" lang="${ui}">${!p.checked?sceneImage:''}<p class="intent-context">${quotedText(x.context)}</p><h2>${quotedText(x.prompt)}</h2>${p.checked?'':`<section class="intent-listen"><div class="audio-text-row"><p>${c.weather?label('날씨 안내를 들어 보세요.','天気の案内を聞きましょう。'):label('상대의 답을 들어 보세요.','相手の返事を聞きましょう。')}</p>${audio()}</div><details class="intent-transcript"><summary>${label('문장 보기','文を見る')}</summary>${transcript}</details></section>`}${p.checked?`<section class="intent-result" role="status">${resultAnswer}<h3>${label('이 말이 단서예요.','この言葉が手がかりです。')}</h3>${transcript}<p class="scenario-feedback">${quotedText(x.hint)}</p></section>`:`<div class="scenario-choices">${choices.map((o,i)=>button(c.weather?learningText(o,o===x.answer?x.answerParts:undefined):quotedText(o),'scenario-select',`secondary${p.selected===i?' selected':''}`,`data-id="${i}" aria-pressed="${p.selected===i}"${c.weather?` lang="${lang}" data-choice-audio="choice:${i===answerIndex?0:i<answerIndex?i+1:i}"`:''}`)).join('')}</div>${c.weather?`<details class="chat-choice-meanings"><summary>${label('선택지 뜻 보기','選択肢の意味')}</summary><ol>${meanings.map(m=>`<li>${quotedText(m)}</li>`).join('')}</ol></details>`:''}${p.retry?`<p class="scenario-feedback lesson-verdict" role="status">${label('다시 듣고 골라 보세요.','もう一度聞いて選びましょう。')}</p>`:''}`}<div class="button-pair">${button(scenarioLearnsFirst(l.id)?label('다시 배우기','もう一度学ぶ'):label('이전','戻る'),'scenario-previous','secondary')}${p.checked?button(p.index===l.count-1?label('학습 마치기','学習を終える'):label('다음','次へ'),'scenario-next'):button(label('확인','確認'),'scenario-check','primary',p.selected===null?'disabled':'')}</div></main>`;
}

export function renderIntentLearning(s,top,l,c){
 const p=scenarioProgress(s),x=c.items[p.index],jp=s.courseDirection==='ja-ko',label=(ko,ja)=>jp?ja:ko;
 return `${top(`${lessonNumberWithVideo(s,l.number[s.courseDirection])}. ${scenarioTitle(s,l)}`)}<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(p.index*2/(l.count*2)*100)}"><span style="width:${p.index*2/(l.count*2)*100}%"></span></div><main class="page scenario-page scenario-learning" lang="${jp?'ja':'ko'}"><h1>${label('대화 익히기','会話を覚える')}</h1><p>${quotedText(x.context)}</p><article class="dialogue-bubble"><div class="audio-text-row"><p lang="${jp?'ko':'ja'}">${dialogueText(x.text,x.phrases,jp?'ko':'ja')}</p>${button(icon('sound'),'scenario-audio','icon-button',`data-id="prompt" aria-label="${label('다시 듣기','もう一度聞く')}"`)}</div><p class="dialogue-meaning">${quotedText(x.meaning)}</p></article><p class="scenario-learning-note">${quotedText(x.hint)}</p><div class="button-pair">${button(label('이전','戻る'),'scenario-previous','secondary')}${button(label('연습하기','練習する'),'scenario-next')}</div></main>`;
}
